let OBJ_SEQ=1;
function esc(v){return typeof VSX?.esc==='function'?VSX.esc(String(v??'')):String(v??'')}
function srcObj(id){return{id,def:{tags:['environment','world_object']}}}
function clampN(v,a,b){return Math.max(a,Math.min(b,v))}
function ensure(o){if(!o||!EXT_SET.has(o.type)||o.vsxObjReady)return o;const c=CFG[o.type]||{};o.vsxObjReady=true;o.vsxObjectId=OBJ_SEQ++;o.r=c.r||18;o.life=c.life||90;o.hp=c.hp||99999;o.maxHp=o.hp;o.vsx={active:0,cd:0,charge:0,stored:0,angle:0,progress:0,contract:null,opened:false,pulse:0,seen:new WeakSet(),tokens:6,release:[],releaseCd:0};if(o.type==='void_well')o.vsx.active=10;if(o.type==='reflector_node')o.vsx.angle=0;if(o.type==='mutation_prism')o.vsx.tokens=6;return o}
function consumeProjectile(p){if((p.pierce||0)<=0)p.dead=true;else p.pierce=Math.max(0,(p.pierce||0)-1)}
function shotHits(o,cb){for(const p of (game.projectiles||[]).slice(-360)){if(!p||p.dead)continue;const key='wo'+o.vsxObjectId;(p.vsxWorldObjectHits ||= new Set());if(p.vsxWorldObjectHits.has(key))continue;if(Math.hypot(p.x-o.x,p.y-o.y)<=o.r+(p.radius||4)){p.vsxWorldObjectHits.add(key);cb(p)}}}
function nearestAlly(){const list=(game.storyAllies||[]).filter(a=>a&&!a.dead&&Number.isFinite(a.hp)&&a.maxHp>0);list.sort((a,b)=>(a.hp/a.maxHp)-(b.hp/b.maxHp));return list[0]||null}
function strongestEnemy(range=900){if(!game?.player)return null;const list=(game.enemies||[]).filter(e=>e&&!e.dead&&!e.isCaptive&&!e.isBoss&&Math.hypot(e.x-game.player.x,e.y-game.player.y)<=range);list.sort((a,b)=>(Number(!!b.elite)-Number(!!a.elite))||(b.maxHp||b.hp||0)-(a.maxHp||a.hp||0));return list[0]||null}
function bestWeapon(){const ws=(game?.player?.weapons||[]).filter(w=>w&&!w.def?.rewardOnly);if(!ws.length)return null;return [...ws].sort((a,b)=>(b.level||1)-(a.level||1)||(b.def?.rarity==='legendary'?1:0)-(a.def?.rarity==='legendary'?1:0))[0]}
function safeProj(o){return o&&Number.isFinite(o.x)&&Number.isFinite(o.y)&&Number.isFinite(o.vx)&&Number.isFinite(o.vy)}
function activeOf(type){return (game?.worldObjects||[]).find(o=>o&&!o.dead&&o.type===type&&o.vsx?.active>0)}
function isAbilityDebt(){return !!(activeOf('void_loan_terminal')?.vsx?.phase==='debt')}
function isNullUltimateBlocked(){const o=activeOf('null_field_generator'),p=game?.player;return !!(o&&p&&Math.hypot(p.x-o.x,p.y-o.y)<=175)}
function activePrompt(o){const s=o.vsx||{};
 const hp=window.VSX_SETTINGS_V5?.holdProgressFor?.(o);if(hp!=null&&hp<1)return L(`HOLD E · CONFIRM ${Math.round(hp*100)}%`,`GIỮ E · XÁC NHẬN ${Math.round(hp*100)}%`);
 if(o.type==='fountain'&&(o.vsxPulseCd||0)>0)return L(`PASSIVE HEAL · PULSE ${Math.ceil(o.vsxPulseCd)}s`,`HỒI THỤ ĐỘNG · XUNG ${Math.ceil(o.vsxPulseCd)}s`);
 if(o.type==='stasis_pylon')return s.active>0?L(`STASIS ACTIVE ${s.active.toFixed(1)}s`,`ĐÌNH TRỆ ${s.active.toFixed(1)}s`):s.cd>0?L(`RECHARGE ${Math.ceil(s.cd)}s`,`SẠC ${Math.ceil(s.cd)}s`):PROMPTS[o.type][VSX.lang];
 if(o.type==='phase_anchor'&&s.anchor)return L(`E · REWIND ${Math.ceil(s.anchorTime||0)}s`,`E · QUAY LẠI ${Math.ceil(s.anchorTime||0)}s`);
 if(o.type==='bounty_terminal'&&s.contract)return L(`BOUNTY ${game.kills-s.contract.start}/${s.contract.goal} · ${Math.ceil(s.contract.time)}s`,`HỢP ĐỒNG ${game.kills-s.contract.start}/${s.contract.goal} · ${Math.ceil(s.contract.time)}s`);
 if(o.type==='risk_cache'&&s.opening)return L(`OPENING ${Math.round(s.progress/1.5*100)}%`,`ĐANG MỞ ${Math.round(s.progress/1.5*100)}%`);
 if(o.type==='resonance_crystal')return L(`SHOOT · CHARGE ${Math.round(s.charge||0)}%`,`BẮN · NẠP ${Math.round(s.charge||0)}%`);
 if(o.type==='xp_reactor')return L(`XP BANK ${Math.round(s.stored||0)}/60`,`NGÂN XP ${Math.round(s.stored||0)}/60`);
 if(o.type==='sanctum_gate')return L(`NEARBY KILLS ${Math.round(s.charge||0)}/12`,`HẠ GẦN ${Math.round(s.charge||0)}/12`);
 if(o.type==='ally_resupply'){const a=nearestAlly();return a?L(`RESUPPLY ${Math.round((s.progress||0)/4*100)}%`,`TIẾP TẾ ${Math.round((s.progress||0)/4*100)}%`):L('NEEDS A LIVING ALLY','CẦN ALLY CÒN SỐNG')}
 if(o.type==='chrono_snapshot'&&s.snapshot)return L(`REWIND IN ${Math.ceil(s.active)}s`,`QUAY LẠI SAU ${Math.ceil(s.active)}s`);
 if(o.type==='void_loan_terminal'&&s.phase==='borrow')return L(`BORROW WINDOW ${s.active.toFixed(1)}s`,`CỬA SỔ VAY ${s.active.toFixed(1)}s`);
 if(o.type==='void_loan_terminal'&&s.phase==='debt')return L(`ABILITY DEBT ${s.active.toFixed(1)}s`,`NỢ KỸ NĂNG ${s.active.toFixed(1)}s`);
 if(o.type==='predator_scanner'&&s.target&&!s.target.dead)return L(`MARKED · ${Math.ceil(s.active)}s`,`ĐÃ ĐÁNH DẤU · ${Math.ceil(s.active)}s`);
 if(o.type==='polarity_core'&&s.active>0)return `${s.polarity>0?'CYAN':'MAGENTA'} · ${Math.ceil(s.active)}s`;
 if(o.type==='momentum_ring')return L(`CIRCUIT ${Math.min(100,Math.round((s.turn||0)/(Math.PI*2)*100))}%`,`VÒNG CHẠY ${Math.min(100,Math.round((s.turn||0)/(Math.PI*2)*100))}%`);
 if(o.type==='entropy_clock'&&s.active>0)return L(`ENTROPY ${Math.round((1-s.active/12)*100)}%`,`ENTROPY ${Math.round((1-s.active/12)*100)}%`);
 if(o.type==='null_field_generator'&&s.active>0)return L(`NULL FIELD ${Math.ceil(s.active)}s`,`TRƯỜNG TRIỆT TIÊU ${Math.ceil(s.active)}s`);
 if(o.type==='soul_ledger'&&s.active>0)return L(`SOULS ${s.kills||0}/10`,`LINH HỒN ${s.kills||0}/10`);
 if(o.type==='reality_dice'&&s.active>0)return `${String(s.mode||'REALITY').replaceAll('_',' ').toUpperCase()} · ${Math.ceil(s.active)}s`;
 if(o.type==='blood_moon_beacon'&&s.active>0)return L(`BLOODBOUND ${s.kills||0} · ${Math.ceil(s.active)}s`,`HUYẾT PHƯỢC ${s.kills||0} · ${Math.ceil(s.active)}s`);
 if(o.type==='projectile_bank'&&s.phase==='bank')return L(`BANK ${s.storedShots?.length||0}/60 · ${Math.ceil(s.active)}s`,`GỬI ${s.storedShots?.length||0}/60 · ${Math.ceil(s.active)}s`);
 if(o.type==='projectile_bank'&&s.phase==='release')return L(`SALVO ${s.release?.length||0}` ,`LOẠT BẮN ${s.release?.length||0}`);
 if(o.type==='death_insurance_terminal'&&s.active>0)return L(`INSURED ${Math.ceil(s.active)}s`,`ĐÃ BẢO HIỂM ${Math.ceil(s.active)}s`);
 return PROMPTS[o.type]?.[VSX.lang]||PROMPTS[o.type]?.en||'';
}

