class VSX_EchoForgeAlly{
 constructor(x,y,target){this.x=x;this.y=y;this.life=target?.elite?13:18;this.dead=false;this.r=13;this.cool=.2;this.sourceType=target?.type||'grunt';this.color=target?.def?.color||'#69dcff';this.damage=Math.max(12,(target?.damage||14)*(target?.elite?1.15:.8));this.speed=target?.elite?430:390}
 update(dt){this.life-=dt;this.cool-=dt;if(this.life<=0){this.dead=true;return}const t=game.findNearest(this.x,this.y,620);if(t){const d=Math.hypot(t.x-this.x,t.y-this.y)||1,n=normalize(t.x-this.x,t.y-this.y);if(d>185){this.x+=n.x*this.speed*dt;this.y+=n.y*this.speed*dt}if(this.cool<=0){this.cool=.62/Math.max(.7,game.allyAttackSpeedMultiplier());game.projectiles.push(new Projectile({x:this.x,y:this.y,vx:n.x*560,vy:n.y*560,radius:4,damage:this.damage*game.player.damageMultiplier*.55*game.allyDamageMultiplier(),life:1.5,pierce:0,color:this.color,weapon:srcObj('echo_forge_ally')}))}}else{const p=game.player,n=normalize(p.x-this.x,p.y-this.y);if(Math.hypot(p.x-this.x,p.y-this.y)>150){this.x+=n.x*300*dt;this.y+=n.y*300*dt}}}
 render(g){g.save();g.globalAlpha=.58;g.fillStyle=this.color;g.strokeStyle='#dffaff';g.shadowBlur=14;g.shadowColor=this.color;g.beginPath();g.arc(this.x,this.y,this.r,0,Math.PI*2);g.fill();g.stroke();g.globalAlpha=.75;g.font='900 8px Arial';g.textAlign='center';g.fillStyle='#fff';g.fillText('ECHO',this.x,this.y+3);g.restore()}
}
class VSX_WeaponRelayTurret{
 constructor(x,y,source){this.x=x;this.y=y;this.life=18;this.dead=false;this.r=13;this.cool=.15;this.weapon=new WeaponInstance(source.id);this.weapon.level=source.level||1;this.weapon.mutationId=source.mutationId||null;this.color=source.def?.tags?.includes('fire')?'#ff8b55':source.def?.tags?.includes('electric')?'#fff06a':source.def?.tags?.includes('ice')?'#8eeeff':'#ffd96a'}
 update(dt){this.life-=dt;this.cool-=dt;if(this.life<=0){this.dead=true;return}const s=this.weapon.getStats?.()||this.weapon.def||{},t=game.findNearest(this.x,this.y,Math.max(420,s.range||620));if(!t||this.cool>0)return;this.cool=clampN((s.cooldown||.8)*.72,.20,1.2);const n=normalize(t.x-this.x,t.y-this.y),tags=this.weapon.def?.tags||[],damage=Math.max(7,(s.damage||15)*.52*game.player.damageMultiplier),spd=Math.max(380,s.speed||560);if(tags.includes('beam')){game.damageEnemy(t,damage*1.1,{source:this.weapon,canCrit:true,damageType:'arcane',fromX:this.x,fromY:this.y});game.beams.push({x1:this.x,y1:this.y,x2:t.x,y2:t.y,width:2.2,color:this.color,life:.09});return}if(tags.includes('area')&&!tags.includes('projectile')){game.explosion(t.x,t.y,Math.max(70,(s.area||90)*.72),damage,this.color,35,this.weapon,false);return}game.projectiles.push(new Projectile({x:this.x,y:this.y,vx:n.x*spd,vy:n.y*spd,radius:Math.max(3,Math.min(9,(s.size||5)*.8)),damage,life:1.6,pierce:Math.min(3,s.pierce||0),bounce:Math.min(2,s.bounce||0),color:this.color,weapon:this.weapon,projectileStyle:tags.includes('football')?'football':null}))}
 render(g){g.save();g.fillStyle='#4d5666';g.strokeStyle=this.color;g.lineWidth=2;g.fillRect(this.x-12,this.y-9,24,18);g.strokeRect(this.x-12,this.y-9,24,18);g.beginPath();g.arc(this.x,this.y-14,5,0,Math.PI*2);g.fillStyle=this.color;g.fill();g.restore()}
}
class VSX_MirrorDoppel extends Enemy{
 constructor(x,y,cid){super('grunt',x,y,1,null);this.isMirrorDoppel=true;this.characterId=cid||'striker';this.size=16;this.maxHp=Math.max(180,game.player.maxHp*2.7+game.wave*25);this.hp=this.maxHp;this.speed=145;this.damage=Math.max(8,game.player.maxHp*.055);this.xp=95;this.def={...this.def,color:'#ff77c8',shape:'circle',label:'M'};this.shotTimer=.4;this.starter=CHARACTER_DEFINITIONS?.[this.characterId]?.weapon||game.player.weapons?.[0]?.id||'pulse_blaster'}
 update(dt){this.flash=Math.max(0,this.flash-dt);this.shotTimer-=dt;const p=game.player,d=Math.hypot(p.x-this.x,p.y-this.y)||1,n=normalize(p.x-this.x,p.y-this.y);if(d>250){this.x+=n.x*this.speed*dt;this.y+=n.y*this.speed*dt}else if(d<150){this.x-=n.x*this.speed*.55*dt;this.y-=n.y*this.speed*.55*dt}if(this.shotTimer<=0){const def=WEAPON_DEFINITIONS[this.starter]||WEAPON_DEFINITIONS.pulse_blaster;this.shotTimer=clampN((def.cooldown||1)*.85,.42,1.45);const football=(def.tags||[]).includes('football'),spd=Math.max(220,(def.speed||430)*.55);game.enemyProjectiles.push(new Projectile({x:this.x,y:this.y,vx:n.x*spd,vy:n.y*spd,radius:football?8:5,damage:this.damage,life:2.8,color:'#ff77c8',owner:'enemy',critAllowed:false,projectileStyle:football?'football':null}))}if(d<this.size+p.radius)p.takeDamage(this.damage*.55,{fromX:this.x,fromY:this.y,enemy:this,physical:true})}
 die(drop=true){if(this.dead)return;super.die(false);game.chests.push(new Chest(this.x,this.y));game.player.gainXP(120);game.pickups.push(new Pickup(this.x+18,this.y,'golden_boost'));VSX.announce(L('MIRROR BROKEN','ĐÃ PHÁ BẢN SAO'),L('PREMIUM REWARD','PHẦN THƯỞNG CAO CẤP'),'#ff77c8')}
 render(g){g.save();g.translate(this.x,this.y);g.shadowBlur=16;g.shadowColor='#ff77c8';g.globalAlpha=.82;g.fillStyle='#351934';g.beginPath();g.arc(0,0,this.size+4,0,Math.PI*2);g.fill();g.strokeStyle='#ff77c8';g.lineWidth=3;g.stroke();g.fillStyle='#fff';g.font='900 11px Arial';g.textAlign='center';g.textBaseline='middle';g.fillText('M',0,1);g.restore();const w=48;g.fillStyle='#381521';g.fillRect(this.x-w/2,this.y-30,w,5);g.fillStyle='#ff77c8';g.fillRect(this.x-w/2,this.y-30,w*clampN(this.hp/this.maxHp,0,1),5)}
}

