function label(o,g){const p=game?.player;if(!p)return;const set=VSX.save?.settings||{},bossFocus=!!set.bossFocusMode&&!!((game?.boss&&!game.boss.dead)||(game?.miniBoss&&!game.miniBoss.dead));let mode=set.objectLabels||'nearby';if(mode==='off')return;const mul=Number(set.objectLabelDistance||1),limit=bossFocus?95:(mode==='always'?1200:195*Math.max(.65,Math.min(1.5,mul))),d=Math.hypot(p.x-o.x,p.y-o.y);if(d>limit)return;const cap=bossFocus?1:(mode==='always'?8:4),near=(game.worldObjects||[]).filter(x=>x&&!x.dead&&Math.hypot(p.x-x.x,p.y-x.y)<=limit).sort((a,b)=>Math.hypot(p.x-a.x,p.y-a.y)-Math.hypot(p.x-b.x,p.y-b.y)).slice(0,cap);if(!near.includes(o))return;const line=activePrompt(o);if(!line)return;g.save();g.translate(o.x,o.y);g.font='700 8px Arial';g.textAlign='center';g.textBaseline='middle';const max=215,w=Math.min(max,Math.ceil(g.measureText(line).width)+12),y=-(o.r||18)-18;g.fillStyle='rgba(3,10,18,.76)';g.strokeStyle='rgba(115,211,255,.18)';g.lineWidth=1;g.beginPath();g.roundRect(-w/2,y-8,w,16,5);g.fill();g.stroke();g.fillStyle='#c5e7f3';g.fillText(line,0,y);g.restore()}
VSX_WorldObject.prototype.render=function(g){ensure(this);if(EXT_SET.has(this.type))drawExt(this,g);else RENDER_BASE.apply(this,arguments);label(this,g)};

