const TAKE_BASE=Player.prototype.takeDamage;
Player.prototype.takeDamage=function(amount,src={}){if(game?.worldObjects?.some(o=>!o.dead&&o.type==='ward_totem'&&Math.hypot(o.x-this.x,o.y-this.y)<=105)){amount*=.85;if(game.stats)game.stats.damagePrevented=(game.stats.damagePrevented||0)+amount*(.15/.85)}return TAKE_BASE.call(this,amount,src)};

