const SPAWN_BASE=Game.prototype.spawnWorldObject;
Game.prototype.spawnWorldObject=function(){if(!this.player)return false;const active=(this.worldObjects||[]).filter(o=>!o.dead&&!o.used&&o.type!=='trial_portal').length;if(active>=5)return false;const all=Object.keys(window.VSX_WORLD_OBJECTS?.entries||{}).filter(id=>id!=='trial_portal');if(!all.length)return SPAWN_BASE.apply(this,arguments);this.vsxWorldObjectBag=(this.vsxWorldObjectBag||[]).filter(id=>all.includes(id));if(!this.vsxWorldObjectBag.length){this.vsxWorldObjectBag=[...all];for(let i=this.vsxWorldObjectBag.length-1;i>0;i--){const j=(Math.random()*(i+1))|0;[this.vsxWorldObjectBag[i],this.vsxWorldObjectBag[j]]=[this.vsxWorldObjectBag[j],this.vsxWorldObjectBag[i]]}}let type;if(this.player.hp/Math.max(1,this.player.maxHp)<.35&&Math.random()<.32)type=Math.random()<.55?'fountain':'ally_resupply';else type=this.vsxWorldObjectBag.pop();if(type==='shrine'&&this.worldObjects.some(o=>!o.dead&&!o.used&&o.type==='shrine'))type='crate';const a=Math.random()*Math.PI*2,rr=rand(620,260),o=new VSX_WorldObject(type,this.player.x+Math.cos(a)*rr,this.player.y+Math.sin(a)*rr);ensure(o);this.worldObjects.push(o);try{vsxDiscover('world_objects',type)}catch(_){}return o};

