const GAME_UPDATE_BASE=Game.prototype.update;
const ALL_E_TYPES=new Set([...E_TYPES,'shrine','goal','fountain']);
Game.prototype.update=function(dt){if(window.VSX_SETTINGS_V5?.hitStopActive?.())return;if(this._vsxWoLastTime!=null&&Number.isFinite(this.time)&&this.time+.25<this._vsxWoLastTime){this.vsxDeathInsurance=null;this.vsxPhaseAnchor=null}this._vsxWoLastTime=Number(this.time)||0;const r=GAME_UPDATE_BASE.apply(this,arguments);if(this.state==='PLAYING'&&this.player&&!this.nearRecruitInteractable&&!this.nearTrialPortal){const pool=(this.worldObjects||[]).filter(o=>{if(o.dead||!ALL_E_TYPES.has(o.type))return false;if(o.used&&o.type!=='fountain')return false;if(o.type==='fountain'&&(o.vsxPulseCd||0)>0)return false;if(o.type==='momentum_ring'||o.type==='mutation_prism')return false;return Math.hypot(o.x-this.player.x,o.y-this.player.y)<95}).sort((a,b)=>Math.hypot(a.x-this.player.x,a.y-this.player.y)-Math.hypot(b.x-this.player.x,b.y-this.player.y));const near=pool[0]||null;this.nearInteractable=near;if(near){const ih=document.getElementById('vsxInteractHint');if(ih)ih.style.display='none'}}window.VSX_ARCH?.run('update.after',{game:this,dt,result:r});return r};
const HANDLE_BASE=Game.prototype.handleKey;
Game.prototype.handleKey=function(code){if(this.state==='PLAYING'){
 if(code==='Space'&&(isAbilityDebt()||isNullUltimateBlocked())){VSX.announce(L('ABILITY SUPPRESSED','KỸ NĂNG BỊ KHÓA'),isAbilityDebt()?L('VOID DEBT ACTIVE','ĐANG TRẢ NỢ HƯ KHÔNG'):L('NULL FIELD ACTIVE','TRƯỜNG TRIỆT TIÊU ĐANG HOẠT ĐỘ'),'#b2c8ff');return}
 if(code==='KeyE'&&!this.nearRecruitInteractable&&!this.nearTrialPortal&&!this.nearInteractable&&this.vsxPhaseAnchor?.vsx?.anchor){this.vsxPhaseAnchor.interact();return}
 }return HANDLE_BASE.call(this,code)};
window.VSX_ARCH?.register('dash.before','world-objects.ability-debt',()=>isAbilityDebt()?{handled:true}:false,{priority:120});

